def perevod(n):
    s = ''
    while n != 0:
        s = str(n % 7) + s
        n //= 7
    return s
def f(n):
    s = perevod(n)
    if n % 2 == 0:
        s = '52' + s + '1'
    else:
        if len(s)  == 1:
            s = s + '15'
        else:
            s = s[-1] + s[1:-1] + s[0] + '15'
    return perevod(int(s,7)) #избавляемся от незначащих нулей
for i in range(1,1001):
    if len(f(i)) == 4:
        print(i)
